package de.lazytv.pro.catalog; import java.util.*; public class Catalog { public final List<Category> categories=new ArrayList<>(); public final List<StreamItem> items=new ArrayList<>(); public boolean isEmpty(){return items.isEmpty();} public List<Category> categories(CatalogType t){List<Category> r=new ArrayList<>();for(Category c:categories)if(c.type==t)r.add(c);return r;} public List<StreamItem> items(CatalogType t,String category){List<StreamItem> r=new ArrayList<>();for(StreamItem i:items)if(i.type==t&&(category==null||category.equals(i.categoryId)))r.add(i);return r;} }